 {isAdmin&&!crossManifest&&<div className="stats">{[{label:'Frete total',value:brl(total),sub:`${rows.length} conhecimentos no manifesto`,icon:FileText},{label:'Total recebido',value:brl(received),sub:`${rows.filter((r:any)=>status(r)==='Pago').length} conhecimentos quitados`,icon:Wallet},{label:'Saldo a receber',value:brl(total-received),sub:'Valores pendentes e parciais',icon:Clock},{label:'Pagamentos parciais',value:String(rows.filter((r:any)=>status(r)==='Parcial').length).padStart(2,'0'),sub:'Com justificativa registrada',icon:AlertCircle}].map((s,i)=><section className={'stat stat'+i} key={s.label}><div>{s.label}<s.icon size={18}/></div><strong>{s.value}</strong><small>{s.sub}</small></section>)}</div>}
